282	    // ------------------------------------------------------------------
283	    // 幂等
284	    // ------------------------------------------------------------------
285	
286	    @Test
287	    void sameRequestIdAndParamsReplaysOriginalResult() {
288	        String rid = requestId();
289	        RegisterArtifactRequest request = artifact("app", 1, dep("lib", 1, 1));
290	        ArtifactResponse first = service.registerArtifact(rid, request);
291	        ArtifactResponse replay = service.registerArtifact(rid, request);
292	
293	        assertThat(replay.repositoryVersion()).isEqualTo(first.repositoryVersion());
294	        assertThat(replay.createdAt()).isEqualTo(first.createdAt());
295	        assertThat(jdbcTemplate.queryForObject(
296	                "SELECT COUNT(1) FROM artifact WHERE name = 'app'", Integer.class)).isEqualTo(1);
297	        assertThat(jdbcTemplate.queryForObject(
298	                "SELECT COUNT(1) FROM idempotent_request", Integer.class)).isEqualTo(1);
299	        // 重放不再推进仓库版本。
300	        assertThat(jdbcTemplate.queryForObject(
301	                "SELECT version FROM repository_state WHERE id = 1", Long.class)).isEqualTo(1L);
302	    }
303	
304	    @Test
305	    void sameRequestIdDifferentParamsReturns409() {
306	        String rid = requestId();
307	        service.registerArtifact(rid, artifact("app", 1));
308	        assertThatThrownBy(() -> service.registerArtifact(rid, artifact("app", 2)))
309	                .isInstanceOfSatisfying(ApiException.class,
310	                        e -> assertThat(e.getStatus()).isEqualTo(409));
311	    }
