313	    @Test
314	    void sameRequestIdAcrossOperationsReturns409() {
315	        String rid = requestId();
316	        service.registerArtifact(rid, artifact("app", 1));
317	        assertThatThrownBy(() -> service.withdrawArtifact(rid, "app", 1))
318	                .isInstanceOfSatisfying(ApiException.class,
319	                        e -> assertThat(e.getStatus()).isEqualTo(409));
320	    }
