322	    @Test
323	    void failedBusinessCallDoesNotConsumeRequestId() {
324	        String rid = requestId();
325	        // 超限失败（422）不应占用 requestId。
326	        for (int v = 1; v <= 5; v++) {
327	            service.registerArtifact(requestId(), artifact("app", v));
328	        }
329	        assertThatThrownBy(() -> service.registerArtifact(rid, artifact("app", 6)))
330	                .isInstanceOf(ApiException.class);
331	
332	        // 同一 requestId 用于另一个合法请求应成功并留档。
333	        ArtifactResponse later = service.registerArtifact(rid, artifact("other", 1));
334	        assertThat(later.name()).isEqualTo("other");
335	        assertThat(jdbcTemplate.queryForObject(
336	                "SELECT COUNT(1) FROM idempotent_request WHERE request_id = ?",
337	                Integer.class, rid)).isEqualTo(1);
338	    }
