/** 无策略旧锁定图的路径展示：仅附带证明命中信息，不产生违规。 */
private List<ProvenancePolicyEvaluator.CoordinateProvenance> inspectWithoutPolicy(
        TreeMap<String, ArtifactVersion> chosen, String rootName) {
    ProvenancePolicy empty = new ProvenancePolicy("", 0, Instant.now(clock), List.of());
    return ProvenancePolicyEvaluator.inspect(chosen, rootName, empty, (name, version) -> {
        ProvenanceAttestation latest = provenanceDao.loadLatestAttestation(name, version);
        if (latest == null || latest.revoked()) {
            return new ProvenancePolicyEvaluator.LookupResult(
                    ProvenancePolicyEvaluator.LookupResult.State.VALID, null);
        }
        return new ProvenancePolicyEvaluator.LookupResult(
                ProvenancePolicyEvaluator.LookupResult.State.VALID, latest);
